        letter-spacing: 0.01em;
        margin-bottom: clamp(2rem, 5vw, 3rem);
      }

      .logo-mark {
        width: 2rem;
        height: 2rem;
        border-radius: 0.45rem;
        background: linear-gradient(140deg, #0f766e, #155e75);
        display: grid;
        place-items: center;
        color: #fff;
        font-size: 0.95rem;
        font-weight: 700;
      }

      h1 {
        margin: 0;
        font-size: clamp(1.75rem, 4.4vw, 2.45rem);
        font-weight: 600;
        letter-spacing: -0.015em;
      }

      .lead {
        margin: 0.75rem auto 0;
        max-width: 42ch;
        color: var(--text-secondary);
        font-size: clamp(1rem, 2vw, 1.08rem);
      }

      .search-wrap {
        margin: clamp(1.75rem, 4vw, 2.25rem) auto 0;
        width: min(100%, 35rem);
      }

      .search-form {
        position: relative;
      }

      .search-input {
        width: 100%;
        height: 3.3rem;
        border: 1px solid var(--border);
        border-radius: 0.75rem;
        padding: 0 3.2rem 0 1rem;
        font: inherit;
        color: var(--text);
        background: #fff;
      }

      .search-input::placeholder {
        color: #6b7280;
      }

      .search-input:focus,
      .search-btn:focus-visible,
      .text-link:focus-visible,
      .cookie-btn:focus-visible,
      .policy-link:focus-visible,
      .modal-btn:focus-visible {
        outline: 3px solid color-mix(in srgb, var(--focus) 40%, white);
        outline-offset: 1px;
      }

      .search-btn {
        position: absolute;
        right: 0.4rem;
        top: 50%;
        transform: translateY(-50%);
        width: 2.5rem;
        height: 2.5rem;
        border-radius: 0.6rem;
        border: none;
        background: var(--accent-soft);
        color: #0c4f49;
        cursor: pointer;
      }

      .search-btn:hover {
        background: #cde8e3;
      }

      .code-panel {
        margin: clamp(1.25rem, 3.5vw, 1.9rem) auto 0;
        background: var(--surface);
        border: 1px solid #e2e8ee;
        border-radius: 0.8rem;
        padding: 1.05rem 1rem;
        width: min(100%, 35rem);
      }

      .code-text {
        margin: 0;
        color: #69737f;
        font-weight: 500;
        letter-spacing: 0.03em;
      }

      .hero-code {
        margin: 1.1rem 0 0;
        font-size: clamp(4rem, 14vw, 7.6rem);
        line-height: 0.95;
        letter-spacing: -0.04em;
        color: #d9e0e5;
        font-weight: 700;
        user-select: none;
      }

      .divider {
        border: none;
        border-top: 1px solid #dfe5ea;
        margin: 1.25rem auto 0;
        width: min(100%, 35rem);
      }

      .next {
        margin: 1.5rem auto 0;
        width: min(100%, 35rem);
      }

      .next h2 {
        margin: 0;
        font-size: 1.03rem;
        font-weight: 600;
      }

      .links {
        margin: 0.9rem 0 0;
        padding: 0;
        list-style: none;
        display: grid;
        gap: 0.55rem;
      }

      .text-link {
        color: var(--muted-link);
        text-decoration: underline;
        text-underline-offset: 3px;
        font-weight: 500;
      }

      .text-link:hover {
        color: #374151;
      }

      .cookie-banner {
        position: fixed;
        left: 0;
        right: 0;
        bottom: 0;
        border-top: 1px solid #d7e0e6;
        background: #f9fbfc;
        box-shadow: 0 -8px 20px rgba(7, 21, 34, 0.05);
      }

      .cookie-inner {
        width: min(1100px, 100%);
        margin: 0 auto;
        padding: 0.95rem 1rem;
        display: flex;
        flex-wrap: wrap;
        gap: 0.75rem 1rem;
        align-items: center;
        justify-content: space-between;
      }

      .cookie-text {
        margin: 0;
        color: #475569;
        font-size: 0.92rem;
        max-width: 78ch;
      }

      .policy-link {
        color: #556271;
      }

      .cookie-btn {
        border: 1px solid #c4d0d9;
        background: white;
        color: #1f2937;
        font: inherit;
        font-weight: 600;
        border-radius: 0.55rem;
        padding: 0.58rem 0.95rem;
        cursor: pointer;
        white-space: nowrap;
      }

      .cookie-btn:hover {
        background: #f2f6f8;
      }

      .modal-backdrop {
        position: fixed;
        inset: 0;
        background: rgba(5, 20, 34, 0.45);
        display: none;
        align-items: center;
        justify-content: center;
        padding: 1rem;
        z-index: 20;
      }

      .modal-backdrop.open {
        display: flex;
      }

      .modal {
        width: min(100%, 34rem);
        background: #fff;
        border-radius: 0.9rem;
        border: 1px solid #dde5eb;
        box-shadow: var(--shadow);
        padding: 1.2rem;
      }

      .modal h3 {
        margin: 0;
        font-size: 1.12rem;
      }

      .modal p {
        margin: 0.55rem 0 0;
        color: #4b5563;
        font-size: 0.96rem;
      }

      .preference-row {
        margin-top: 1rem;
        display: flex;
        align-items: center;
        justify-content: space-between;
        gap: 0.8rem;
        padding: 0.78rem;
        border: 1px solid #e2e8ee;
        border-radius: 0.65rem;
      }

      .preference-label {
        font-size: 0.95rem;
        color: #1f2937;
      }

      .toggle {
        appearance: none;
        width: 2.65rem;
        height: 1.5rem;
        border-radius: 999px;
        background: #cbd5e1;
        position: relative;
        cursor: pointer;
      }

      .toggle::before {
        content: "";
        position: absolute;
        width: 1.1rem;
        height: 1.1rem;
        border-radius: 50%;
        background: #fff;
        top: 0.2rem;
        left: 0.2rem;
        transition: 0.2s ease;
      }

      .toggle:checked {
        background: #0f766e;
      }

      .toggle:checked::before {
        left: 1.35rem;
      }

      .modal-actions {
        margin-top: 1rem;
        display: flex;
        justify-content: flex-end;
        gap: 0.5rem;
      }

      .modal-btn {
        border: 1px solid #cad4dc;
        border-radius: 0.55rem;
        background: #fff;
        color: #1f2937;
        padding: 0.55rem 0.9rem;
        font: inherit;
        cursor: pointer;
      }

      .modal-btn.primary {
        background: #0f766e;
        color: #fff;
        border-color: #0f766e;
      }

      @media (max-width: 640px) {
        .page {
          align-items: flex-start;
          padding-top: 2rem;
        }

        .hero-code {
          margin-top: 0.8rem;
        }

        .cookie-inner {
          align-items: flex-start;
        }
      }
