    <section class="cookie-banner" id="cookieBanner" role="region" aria-label="Cookie consent">
      <div class="cookie-inner">
        <p class="cookie-text">
          This website utilizes technologies such as cookies to enable essential site functionality, as well as for
          analytics, personalization, and targeted advertising. To learn more, view the following link:
          <a class="policy-link" href="./privacy-policy.html" target="_blank" rel="noopener">Privacy Policy</a>
        </p>
        <button class="cookie-btn" id="managePrefsBtn" type="button">Manage Preferences</button>
      </div>
    </section>

    <div class="modal-backdrop" id="prefsModal" aria-hidden="true">
      <section class="modal" role="dialog" aria-modal="true" aria-labelledby="prefsTitle">
        <h3 id="prefsTitle">Cookie Preferences</h3>
        <p>Control how IdeaForum uses cookies and similar technologies.</p>

        <label class="preference-row">
          <span class="preference-label">Essential cookies (always active)</span>
          <input class="toggle" type="checkbox" checked disabled />
        </label>
        <label class="preference-row">
          <span class="preference-label">Analytics cookies</span>
          <input class="toggle" id="analyticsToggle" type="checkbox" checked />
        </label>
        <label class="preference-row">
          <span class="preference-label">Personalization cookies</span>
          <input class="toggle" id="personalizationToggle" type="checkbox" />
        </label>

        <div class="modal-actions">
          <button class="modal-btn" id="closeModalBtn" type="button">Cancel</button>
          <button class="modal-btn primary" id="savePrefsBtn" type="button">Save Preferences</button>
        </div>
      </section>
    </div>

    <script>
      const searchForm = document.getElementById("searchForm");
      const searchInput = document.getElementById("searchInput");
      const cookieBanner = document.getElementById("cookieBanner");
      const managePrefsBtn = document.getElementById("managePrefsBtn");
      const prefsModal = document.getElementById("prefsModal");
      const closeModalBtn = document.getElementById("closeModalBtn");
      const savePrefsBtn = document.getElementById("savePrefsBtn");

      function openModal() {
        prefsModal.classList.add("open");
        prefsModal.setAttribute("aria-hidden", "false");
        closeModalBtn.focus();
      }

      function closeModal() {
        prefsModal.classList.remove("open");
        prefsModal.setAttribute("aria-hidden", "true");
        managePrefsBtn.focus();
      }

      searchForm.addEventListener("submit", (event) => {
        event.preventDefault();
        const query = searchInput.value.trim();
        if (!query) return;
        const encoded = encodeURIComponent(query);
        window.location.href = `./search-results.html?q=${encoded}`;
      });

      managePrefsBtn.addEventListener("click", openModal);
      closeModalBtn.addEventListener("click", closeModal);

      savePrefsBtn.addEventListener("click", () => {
        cookieBanner.style.display = "none";
        closeModal();
      });

      prefsModal.addEventListener("click", (event) => {
        if (event.target === prefsModal) closeModal();
      });

      window.addEventListener("keydown", (event) => {
        if (event.key === "Escape" && prefsModal.classList.contains("open")) {
          closeModal();
        }
      });
    </script>
